def solve(grid):
    row = grid[0]
    n = len(row)
    nz = sum(1 for x in row if x != 0)
    size = nz * n
    out = [[0]*size for _ in range(size)]
    for r in range(size):
        offset = size - 1 - r
        for j in range(n):
            col = offset + j
            if 0 <= col < size:
                out[r][col] = row[j]
    return out
